from django.db import migrations, models
from django.utils.text import slugify


def marcar_portadas_generadas(apps, schema_editor):
    """Las portadas que ya existían y se llaman como el título las hizo el generador.

    El generador nombra el archivo portadas/<nombre-del-titulo>.png; una imagen subida
    por el admin casi nunca se llama así, de modo que no se marca y no se reemplaza.
    """
    Titulo = apps.get_model('modulo', 'Titulo')
    for titulo in Titulo.objects.exclude(portada=''):
        if titulo.portada.name == f'portadas/{slugify(titulo.nombre) or "titulo"}.png':
            titulo.portada_generada = True
            titulo.save(update_fields=['portada_generada'])


